package webpresenter.protocol;

import java.util.List;

/**
 * Every message exchanged between the central server and a MediaPlayer. Each record is the payload
 * of an {@link Envelope}; its wire name comes from {@link MessageType}.
 */
public sealed interface Message {

    // ------------------------------------------------------------------ player → server

    /**
     * First message after the connection opens.
     *
     * @param deviceId persistent id generated by the player on first start
     * @param hostname host name, used as the default device name
     * @param token device token received in {@link Paired}, or null if not paired yet
     */
    record Hello(String deviceId, String hostname, String playerVersion, int protocolVersion,
            List<DisplayInfo> displays, String token) implements Message {

        public Hello {
            displays = displays == null ? List.of() : List.copyOf(displays);
        }
    }

    /**
     * Download progress of everything the player must keep in its cache: the rest screen plus the
     * media of the prepared event. Files are counted once even if used by several items.
     *
     * @param eventId event of the last {@link Prepare} this status covers, or null if none
     * @param itemsFailed files whose download or verification failed (retried on the next PREPARE)
     */
    record CacheStatus(String eventId, int itemsReady, int itemsTotal, int itemsFailed, long bytesReady,
            long bytesTotal) implements Message {

        public boolean complete() {
            return itemsReady == itemsTotal && itemsFailed == 0;
        }
    }

    // ------------------------------------------------------------------ server → player

    /** The device is waiting for operator approval; the player shows the code on screen. */
    record PairingPending(String pairingCode) implements Message {}

    /** The operator approved the device. The player stores the token and sends it in every {@link Hello}. */
    record Paired(String token) implements Message {}

    /**
     * Device settings chosen by the operator. Sent after a successful {@link Hello} and whenever they change.
     *
     * @param displayIndex index of the display used for the presentation window
     * @param restScreen media shown while nothing is playing, or null for a black screen
     */
    record Config(String deviceName, int displayIndex, MediaRef restScreen, Transition transition) implements Message {}

    /**
     * The event the player must be ready to present: all its media must be downloaded before it
     * goes live. Sent on connection and whenever the current event or its items change.
     *
     * @param eventId null when there is no current event (the player may drop event media)
     * @param items in presentation order
     */
    record Prepare(String eventId, String title, List<PlanItem> items) implements Message {

        public Prepare {
            items = items == null ? List.of() : List.copyOf(items);
        }

        public static Prepare none() {
            return new Prepare(null, null, List.of());
        }
    }

    /** The device was removed by an operator; the player forgets its token. */
    record Revoked(String reason) implements Message {}

    // ------------------------------------------------------------------ both directions

    record Error(String code, String message) implements Message {}

    // ------------------------------------------------------------------ value types

    /** A display reported by the player. Sizes are in logical pixels; {@code scale} converts to physical. */
    record DisplayInfo(int index, int width, int height, double scale, boolean primary) {}

    /** A media file the player must download (and verify) before showing it. */
    record MediaRef(String mediaId, MediaKind kind, String url, String sha256, long sizeBytes) {}

    /** One step of an event: either a media file or a text slide rendered by the player. */
    record PlanItem(String itemId, ItemType type, String title, MediaRef media, Slide slide) {}

    record Slide(String title, String body) {}

    enum ItemType { MEDIA, SLIDE }

    record Transition(TransitionType type, int durationMs) {

        public static final Transition DEFAULT = new Transition(TransitionType.FADE, 600);
    }

    enum MediaKind { VIDEO, AUDIO, IMAGE }

    enum TransitionType { CUT, FADE }
}
